// Server-only authored questions. Difficulty labels are a blueprint, not
// empirical calibration. Mobile tests platform-independent mobile principles.
const question = (text, answer, distractors, skills) => ({ text, answer, distractors, skills });
const family = (id, topic, difficulty, questions) => ({
  id, topic, difficulty,
  skills: [...new Set(questions.flatMap(item => item.skills))],
  variants: questions.map((item, index) => {
    const options = [...item.distractors];
    options.splice(index, 0, item.answer);
    return { id: `${id}-${String.fromCharCode(97 + index)}`, text: item.text, options, correct: index, skills: item.skills };
  }),
});

